}

#lcwin{
  max-width:390px;margin:6px auto;background:var(--bg);
  border-radius:18px;overflow:hidden;
  box-shadow:0 8px 40px rgba(0,0,0,.65),0 0 0 1px rgba(255,255,255,.06);
  animation:lci .3s ease both;
}
@keyframes lci{from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:translateY(0)}}

/* ─ HEADER ─ */
#lc-hdr{
  display:flex;align-items:center;gap:9px;padding:12px 15px;
  cursor:pointer;user-select:none;
  background:linear-gradient(135deg,#262740 0%,#1A1B2E 100%);
  border-bottom:1px solid var(--bd);transition:background .18s;position:relative;
}
#lc-hdr::after{
  content:'';position:absolute;bottom:0;left:14px;right:14px;height:1px;
  background:linear-gradient(90deg,transparent,rgba(255,107,157,.35),transparent);
}
#lc-hdr:hover{background:linear-gradient(135deg,#2E2F4E 0%,#22233A 100%)}

.lc-dot{
  width:9px;height:9px;border-radius:50%;background:var(--rd);flex-shrink:0;
  animation:lcdot 2s ease-in-out infinite;
}
.lc-dot.off{background:var(--tx3);animation:none}
@keyframes lcdot{
  0%{box-shadow:0 0 0 0 rgba(255,71,87,.7)}
  60%{box-shadow:0 0 0 7px rgba(255,71,87,0)}
  100%{box-shadow:0 0 0 0 rgba(255,71,87,0)}
}

#lc-title{flex:1;font-size:12.5px;font-weight:800;color:var(--tx);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
